var SessionTimeout = function() {
    var e = function() {
        $.sessionTimeout({
            title: "Aviso de Timeout",
            message: "Sua sessão irá encerrar por falta de uso.",
            keepAliveUrl: "inicial.php",
            redirUrl: "usu_bloqueado.php",
            logoutUrl: "usu_logoff.php",
            warnAfter: 7e4,
            redirAfter: 9e4,
			keepAliveInterval: 5e3,
			
            ignoreUserActivity: !0,
            countdownMessage: "Redirecionando em {timer} segundos.",
            countdownBar: !0
        })
    };
    return {
        init: function() {
            e()
        }
    }
}();
jQuery(document).ready(function() {
    SessionTimeout.init()
});


